export const RIP_ANCHOR = {"clamp": [22.43, 52.34], "open": [22.27, 54.21], "clampAr": 1.0174, "openAr": 0.9143, "star": [49.21, 37.8]} as const;

const FALLBACK = "/assets/stage-pack.webp";

/** The parts for a pack's art. Art with no parts rips as the standard foil pack, so a pack can never stall the bite. */
export function ripParts(art: string) {
  const a = RIP_ART[art] ?? RIP_ART[FALLBACK];
  const part = (name: "top" | "body" | "back") => `/assets/rip/${a.key}-${name}.webp`;
  // The card pack is the hero's pack, so it wears the hero's light. Each NFT pack's is baked from its own art by scripts/bake-stage-idle.mjs.
  const sheen = a.key === "stage-pack" ? HERO_ART.sheen : [0, 1, 2, 3].map((i) => `/assets/rip/${a.key}-sheen-${i}.webp`);
  return { ...a, whole: RIP_ART[art] ? art : FALLBACK, top: part("top"), body: part("body"), back: part("back"), sheen, wax: a.key === "stage-pack" ? HERO_ART.wax : null };
}

/** The stage's sunburst, one square image so it can turn. */
export const RIP_RAYS = "/assets/rip/rays.webp";

/** Everything the bite shows that isn't the pack or the prize, for preloading. The open seal is the hero's sprite, so the idle and the bite are one drawing. */
export const RIP_LAYERS = [...["bg", "star", "pow", "seal-clamp", "shards"].map((n) => `/assets/rip/${n}.webp`), HERO_ART.seal];
